function externalSort(kind){if(kind==='task')return (a,b)=>String(a.deadline_at||'9999').localeCompare(String(b.deadline_at||'9999'))||String(a.priority||'P9').localeCompare(String(b.priority||'P9'))||String(b.updated_at||'').localeCompare(String(a.updated_at||''));if(!['meeting','milestone'].includes(kind))return (a,b)=>String(b.date||b.period_start||'').slice(0,10).localeCompare(String(a.date||a.period_start||'').slice(0,10))||String(b.updated_at||'').localeCompare(String(a.updated_at||''));return (a,b)=>{let k=['meeting'].includes(kind)?'start_at':['task','milestone'].includes(kind)?'deadline_at':'updated_at';let x=a[k]||a.period_start||a.date||a.updated_at||'',y=b[k]||b.period_start||b.date||b.updated_at||'';return ['meeting','task','milestone'].includes(kind)?String(x||'9999').localeCompare(String(y||'9999')):String(y).localeCompare(String(x))}}
const externalHM=s=>externalTime(s)?.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})||'';
