// Today overview: one read-only summary above Desk's own Today content.
// A recurring meeting can qualify for today through a later occurrence: show that occurrence's times.
function externalOccurrenceToday(r){let t=today();if(externalDay(r.start_at)===t||!Array.isArray(r.upcoming_starts))return r;let i=r.upcoming_starts.findIndex(x=>externalDay(x)===t);if(i<0)return r;let s=externalTime(r.start_at),e=externalTime(r.end_at),occ=externalTime(r.upcoming_starts[i]),rest=r.upcoming_starts.slice(i);return {...r,start_at:r.upcoming_starts[i],end_at:s&&e&&occ?new Date(occ.getTime()+(e-s)).toISOString():'',upcoming_starts:rest,upcoming_count:rest.length}}
