function setPurpose(d,value){let key=d.type==='projects'?'objective':'deliverable',re=new RegExp('(^|\\n)(## '+key+'\\n)([\\s\\S]*?)(?=\\n## |$)','i');if(!d.values[key]&&re.test(d.values.body))setField('body',d.values.body.replace(re,(_,a,b)=>a+b+value+'\n'));else setField(key,value)}
async function ensureRecord(){let d=drawer;if(!d.id)d.dirty.add('title');return flushDrawer()}
