$('record-title').oninput=e=>setField('title',e.target.value);$('edit-status').onchange=e=>setField('status',e.target.value);$('edit-date').onchange=e=>setField(d.type==='tasks'?'do_date':'date',e.target.value);if($('edit-due'))$('edit-due').onchange=e=>setField('due_date',e.target.value);if($('body-editor'))$('body-editor').oninput=e=>setField('body',e.target.value);
for(const key of ['authors','publication_date','publication','doi','library'])if($('ref-'+key))$('ref-'+key).onchange=e=>setField(key,e.target.value);
for(const [id,key] of [['edit-from','date_from'],['edit-to','date_to'],['edit-short','display_title'],['edit-domain','domain'],['edit-kind','kind'],['edit-start','start_time'],['edit-end','end_time'],['edit-reading','human_reading']])if($(id))$(id).onchange=e=>setField(key,e.target.value);
$('edit-project').onchange=e=>setField('projects',[...new Set([...(e.target.value?[e.target.value]:[]),...r.projects.slice(1)])]);$('edit-package').onchange=e=>setField('work_packages',[...new Set([...(e.target.value?[e.target.value]:[]),...r.work_packages.slice(1)])]);$('edit-tags').onchange=e=>setField('tags',e.target.value.split(',').map(v=>v.trim()).filter(Boolean));if($('edit-source'))$('edit-source').onchange=e=>{let v=e.target.value.trim();if(v.startsWith('10.'))v='https://doi.org/'+v;setField('sources',[...new Set([...(v?[v]:[]),...r.sources.slice(1)])])};if($('edit-private'))$('edit-private').onchange=e=>setField('private',e.target.checked);
