function isLegacyURL(url){try{return /(^|\.)notion\.(so|site)$/.test(new URL(url).hostname)}catch{return false}}
function renderNote(body){return markdown(body.replace(/^## Import context\n[\s\S]*?\n## Original Notion body\n/,''))}
function noteLocalPath(url){
 if(/^[a-z][a-z0-9+.-]*:|^\/\//i.test(url))return null;
 let original=(drawer?.values.local_paths||[]).find(p=>p.endsWith('.md')&&p.includes('Notion-2026-09-07'));
 let base=original||find(drawer?.id)?.path;if(!base)return null;
 try{let u=new URL(url,'http://local/'+base);return decodeURIComponent(u.pathname.slice(1))}catch{return null}
}
function inline(text){
 const re=/(!?)\[([^\]]+)\]\(([^)]+)\)|\[([\w-]+)\]|\*\*([^*]+)\*\*|`([^`]+)`/g;let out='',last=0,m;
 while((m=re.exec(text))){out+=E(text.slice(last,m.index));
  if(m[5])out+='<strong>'+E(m[5])+'</strong>';
  else if(m[6])out+='<code>'+E(m[6])+'</code>';
  else if(m[4])out+=find(m[4])?`<button class="task-title" data-open="${E(m[4])}">${E(short(find(m[4])))}</button>`:E(m[0]);
  else{let image=m[1],label=m[2],url=m[3],path=noteLocalPath(url),record=path&&records.find(r=>r.path===path);
   if(image){out+=path&&/\.(png|jpe?g|gif|webp)$/i.test(path)?`<a href="${urlFile(path)}" target="_blank" rel="noreferrer"><img class="reading-figure" src="${urlFile(path)}" alt="${E(label)}" loading="lazy"></a>`:E(label)}
   else if(record)out+=`<button class="task-title" data-open="${E(record.id)}">${E(label)}</button>`;
   else if(isLegacyURL(url))out+=E(label);
   else if(/^https?:\/\//i.test(url))out+=`<a href="${E(url)}" target="_blank" rel="noreferrer">${E(label)}</a>`;
   else if(path)out+=`<a href="${urlFile(path)}" target="_blank" rel="noreferrer">${E(label)}</a>`;
   else out+=E(label);
  }last=re.lastIndex;
 }return out+E(text.slice(last));
}
function markdown(body){
 let lines=body.split('\n'),out=[];
 for(let i=0;i<lines.length;i++){let line=lines[i];
  if(/^\|/.test(line)&&/^\|?\s*:?-{3,}/.test(lines[i+1]||'')){
   let cells=s=>s.trim().replace(/^\||\|$/g,'').split('|').map(x=>x.trim());
   let head=cells(line);i+=2;let rows=[];while(i<lines.length&&/^\|/.test(lines[i])){rows.push(cells(lines[i]));i++}i--;
   out.push('<div class="reading-table"><table><thead><tr>'+head.map(x=>'<th>'+inline(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+inline(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>');continue;
  }
  if(/^#{1,6} /.test(line)){let level=Math.min(4,Math.max(2,line.match(/^#+/)[0].length));out.push(`<h${level}>${inline(line.replace(/^#+ /,''))}</h${level}>`)}
  else if(/^- \[[ xX]\] /.test(line))out.push(`<p><button class="check ${line[3].toLowerCase()==='x'?'checked':''}" style="display:inline-grid;margin-right:8px" data-checkline="${i}" aria-label="Toggle ${E(line.slice(6))}">${line[3].toLowerCase()==='x'?'✓':''}</button>${inline(line.slice(6))}</p>`);
  else if(line==='---')out.push('<hr>');
  else if(line)out.push(`<p class="${line.startsWith('- ')?'bullet':''}">${inline(line.replace(/^- /,''))}</p>`);
 }return out.join('');
}
async function prepareMeeting(){let recent=records.filter(r=>r.type==='journal'&&activityDate(r)>=addDays(today(),-6)&&activityDate(r)<=today()),tasks=records.filter(r=>r.type==='tasks'&&isOpen(r));await openNew('meetings',{title:'Meeting · '+dateText(today()),status:'proposed',kind:'1:1',journal:recent.map(r=>r.id),tasks:tasks.map(r=>r.id),body:'## Agenda\n\n## Notes\n\n## Decisions\n'})}
async function prepareReview(){let from=$('review-from').value,to=$('review-to').value;if(!from||!to||from>to)return toast('Choose a valid date range');let journals=records.filter(r=>r.type==='journal'&&activityDate(r)>=from&&activityDate(r)<=to),meetings=records.filter(r=>r.type==='meetings'&&activityDate(r)>=from&&activityDate(r)<=to),tasks=records.filter(r=>r.type==='tasks'&&r.completed_date>=from&&r.completed_date<=to&&isDone(r));let section=(title,rs)=>'## '+title+'\n'+(rs.length?rs.map(r=>'- ['+r.id+']').join('\n'):'No recorded items.')+'\n\n';await openNew('reviews',{title:'Review · '+dateText(from)+' – '+dateText(to),status:'draft',date:to,date_from:from,date_to:to,journal:journals.map(r=>r.id),meetings:meetings.map(r=>r.id),tasks:tasks.map(r=>r.id),body:section('Work recorded',journals)+section('Meetings',meetings)+section('Completed tasks',tasks)+'## Reflections\n\n## Unfinished work\n\n## Next priorities\n'})}
function openSearch(){if(!$('search-dialog').open)$('search-dialog').showModal();$('global-search').value='';searchResults('');$('global-search').focus()}
function searchResults(q){let results=records.filter(r=>[r.title,r.display_title,r.body,...(r.tags||[])].join(' ').toLowerCase().includes(q.toLowerCase())).sort(sortDate).slice(0,25);$('search-results').innerHTML=recentRows(results);$('search-results').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{$('search-dialog').close();openRecord(b.dataset.open)})}
$('global-search').oninput=e=>searchResults(e.target.value);$('search-dialog').onclick=e=>{if(e.target===$('search-dialog'))$('search-dialog').close()};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}else if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'&&drawer){e.preventDefault();flushDrawer()}else if(e.key==='Escape'&&!$('search-dialog').open)closeDrawer();else if(e.key==='n'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!drawer){e.preventDefault();openNew('inbox')}});window.addEventListener('beforeunload',e=>{if(drawer?.dirty.size||drawer?.inflight){e.preventDefault();e.returnValue=''}});
render();
